<?php require_once __DIR__.'/../api/bootstrap.php'; require_login(); $m=current_medico(); $s=db()->prepare('SELECT * FROM modelos_documento WHERE medico_id=? ORDER BY tipo,nome'); $s->execute([$m['id']]); $modelos=$s->fetchAll(); render_header('Modelos'); ?><h1>Modelos personalizados</h1><a class="btn" href="create.php">Novo modelo</a><div class="card"><table><tr><th>Tipo</th><th>Nome</th><th>Ações</th></tr><?php foreach($modelos as $x): ?><tr><td><?=e($x['tipo'])?></td><td><?=e($x['nome'])?></td><td><a href="edit.php?id=<?=$x['id']?>">Editar</a></td></tr><?php endforeach; ?></table></div><?php render_footer(); ?>